{
  "name": "REFRACT",
  "short_name": "REFRACT",
  "start_url": "/REFRACT_APP_v35.html",
  "display": "standalone",
  "background_color": "#050505",
  "theme_color": "#050505",
  "description": "Digital couture — living identity on a 3D watch face.",
  "icons": [
    { "src": "icon-192.png", "sizes": "192x192", "type": "image/png" },
    { "src": "icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any maskable" }
  ]
}

const C = "refract-v35";
const PRECACHE = [
  "/index.html",
  "/REFRACT_APP_v35.html",
  "/app.html",
  "/manifest.json",
  "/assets/studio.hdr"
];

self.addEventListener("install", (e) => {
  e.waitUntil(caches.open(C).then((c) => c.addAll(PRECACHE)));
  self.skipWaiting();
});

self.addEventListener("activate", (e) => {
  e.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((k) => k !== C).map((k) => caches.delete(k)))
    ).then(() => clients.claim())
  );
});

self.addEventListener("fetch", (e) => {
  e.respondWith(
    fetch(e.request)
      .then((r) => {
        const cp = r.clone();
        caches.open(C).then((c) => c.put(e.request, cp));
        return r;
      })
      .catch(() => caches.match(e.request))
  );
});

import React, { useRef, useCallback, useEffect } from 'react';
import { StyleSheet, View, StatusBar, BackHandler, Platform } from 'react-native';
import { WebView } from 'react-native-webview';

// REFRACT v35 shell — loads hosted v35 (3D watch + live face) by default.
// Localhost override: EXPO_PUBLIC_REFRACT_URL=http://localhost:8080/REFRACT_APP_v35.html
const DEFAULT_PROD_URL = 'https://refract-app.vercel.app/REFRACT_APP_v35.html';
const DEFAULT_DEV_URL = 'http://localhost:8080/REFRACT_APP_v35.html';

export default function App() {
  const webRef = useRef(null);
  const canGoBack = useRef(false);

  const fromEnv = process.env.EXPO_PUBLIC_REFRACT_URL;
  const CONFIGURATOR_URL =
    fromEnv ||
    (__DEV__ ? DEFAULT_DEV_URL : DEFAULT_PROD_URL);

  const injected = `
    window.REFRACT_CONFIG = {
      supabaseUrl: ${JSON.stringify(process.env.EXPO_PUBLIC_SUPABASE_URL || '')},
      supabaseAnonKey: ${JSON.stringify(process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY || '')},
      watchModelUrl: ${JSON.stringify(process.env.EXPO_PUBLIC_WATCH_MODEL_URL || '')},
      appVersion: 'v35'
    };
    true;
  `;

  useEffect(() => {
    if (Platform.OS !== 'android') return;
    const onBack = () => {
      if (canGoBack.current) {
        webRef.current?.injectJavaScript(
          'window.__refractBack && window.__refractBack(); true;'
        );
        return true;
      }
      return false;
    };
    const sub = BackHandler.addEventListener('hardwareBackPress', onBack);
    return () => sub.remove();
  }, []);

  const onNav = useCallback((navState) => {
    const rootish =
      /#\/(2d|auth|intro)$/.test(navState.url) || !/#\//.test(navState.url);
    canGoBack.current = !rootish;
  }, []);

  return (
    <View style={styles.container}>
      <StatusBar hidden />
      <WebView
        ref={webRef}
        source={{ uri: CONFIGURATOR_URL }}
        style={styles.webview}
        injectedJavaScriptBeforeContentLoaded={injected}
        onNavigationStateChange={onNav}
        originWhitelist={['*']}
        javaScriptEnabled
        domStorageEnabled
        allowFileAccess
        allowUniversalAccessFromFileURLs
        mixedContentMode="always"
        overScrollMode="never"
        showsVerticalScrollIndicator={false}
        showsHorizontalScrollIndicator={false}
        startInLoadingState
        renderLoading={() => <View style={styles.loading} />}
        onError={(e) => console.warn('WebView error:', e.nativeEvent)}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#050505' },
  webview: { flex: 1, backgroundColor: 'transparent' },
  loading: { position: 'absolute', inset: 0, backgroundColor: '#050505' },
});

